'use client'

import * as React from 'react'

// Every number a player reads is a Stat, including the score in a row. The row
// carries `data-gs-rank` and the Stat inside it carries `data-gs-value`, which
// is the split the attribute contract settles: one element's value cannot carry
// two numbers.
import { Stat } from './stat'

// The player in a row is an Identity: the avatar disc and the name beside it are
// its rendering, so a theme that changes what an avatar looks like reaches every
// row here without this file knowing.
import { Identity } from './identity'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Leaderboard and the typecheck still passes.
import './leaderboard.css'

/**
 * Leaderboard: ranked rows, a pinned "you" row, and an empty case that is not
 * a blank rectangle.
 *
 * It performs nothing. It does not sort, page, fetch or decide who moved: the
 * host owns the order and hands it over already ranked. What this owns is the
 * rendering, the reorder motion, and the announcement, and the announcement is
 * the part that is easy to get wrong.
 *
 * The display details of a player, their name and their secondary line, are
 * props today. They become `identity` once that item lands; see the note on
 * `LeaderboardEntry`.
 */

export interface LeaderboardEntry {
  /** The player's id. Rides `data-gs-player`. */
  id: string
  /** The row's rank, 1-based. The host decides it; this never sorts. */
  rank: number
  /**
   * The player's display name. Player-supplied and therefore untrusted, so it
   * is rendered as text and never as markup. Rendered by `identity`, which
   * draws initials in the avatar disc when there is no picture.
   */
  name: string
  /** Where the player's picture is. The host's URL; `identity` renders it. */
  avatarUrl?: string
  /** The number beside the name. Rendered by `stat`, so it carries `data-gs-value`. */
  score: number
  /**
   * How many places the row just moved, signed. Positive is a gain. There is no
   * separate trend or rank-change attribute: the sign is the direction.
   */
  delta?: number
  /** The current player's row. */
  you?: boolean
  /** The team this row stands for, when it stands for one. */
  team?: string
  /** A secondary line under the name: a team name, a time, a country. */
  detail?: string
}

export interface LeaderboardProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  /** The rows, in the order they should render. This never re-sorts them. */
  entries: LeaderboardEntry[]
  /** The surface's accessible name. */
  label?: string
  /**
   * `list` is the phone board of specimen 3e: 52px rows in one column.
   * `broadcast` is specimen 3f's big-screen treatment of the same rows: two
   * columns, 64px tall, the rank in a coloured disc, the name in the display
   * face. Same attributes, same order, one prop; see `data-gs-presentation`.
   */
  presentation?: 'list' | 'broadcast'
  /**
   * Hold a copy of the player's row on screen while the list scrolls. It is the
   * same row with `data-gs-pinned`, never a second component.
   */
  pinYou?: boolean
  /** The word beside every score. Defaults to `stat`'s own. */
  scoreLabel?: string
  /** Render a score as something other than the bare number. */
  formatScore?: (value: number) => string
  /** The heading of the designed empty case. */
  emptyHeading?: string
  /** The line under it. */
  emptyBody?: string
  /** The designed next step out of the empty case. */
  emptyAction?: React.ReactNode
}

/**
 * The words that go with the states. `you` is fixed by the accessible-name
 * table in the attribute contract; the movement words are this component's, and
 * they are here rather than inline so leaderboard and podium cannot drift.
 */
const STATE_WORD = {
  you: 'you',
  empty: 'nothing here yet',
  up: 'moved up',
  down: 'moved down',
} as const

function movementWords(delta: number | undefined): string | null {
  if (delta === undefined || delta === 0) return null
  return `${delta > 0 ? STATE_WORD.up : STATE_WORD.down} ${Math.abs(delta)}`
}

/** The one sentence a screen reader gets for a row, in reading order. */
function rowSentence(entry: LeaderboardEntry, scoreLabel: string): string {
  const words = [String(entry.rank), entry.name]
  if (entry.detail) words.push(entry.detail)
  words.push(`${scoreLabel} ${entry.score}`)
  if (entry.you) words.push(STATE_WORD.you)
  const movement = movementWords(entry.delta)
  if (movement) words.push(movement)
  return words.join(', ')
}

interface RowProps {
  entry: LeaderboardEntry
  /** The held copy, not the row in the list. */
  pinned?: boolean
  broadcast?: boolean
  scoreLabel: string
  formatScore?: (value: number) => string
}

/**
 * One row. The pinned copy is this component with a second marker, so there is
 * exactly one place a row's shape is decided.
 *
 * The order is the drawing's (specimen 3e): the rank, then which way the row
 * moved, then the player, then the score anchored at the right edge. The
 * movement slot is always rendered. A row that did not move draws a dash in
 * it, which is what keeps the avatars and the scores of every row in one
 * column whether or not the row moved; leaving the slot out was how the
 * scores of still rows sat 12px further from the edge than the rest.
 *
 * Everything visible is `aria-hidden`, and the row carries one sentence for the
 * screen reader instead. Otherwise a rank, a name, a detail and a stat group
 * are announced as four things, and a list of twenty rows reads as eighty.
 */
function Row({ entry, pinned = false, broadcast = false, scoreLabel, formatScore }: RowProps) {
  const movement = movementWords(entry.delta)

  return (
    <li
      className="gs-leaderboard__row"
      data-gs-part={pinned ? 'pinned-row' : 'row'}
      data-gs-rank={entry.rank}
      data-gs-player={entry.id}
      data-gs-team={entry.team}
      data-gs-delta={entry.delta}
      data-gs-you={entry.you ? 'true' : undefined}
      data-gs-pinned={pinned ? 'true' : undefined}
      // The row travels when the order changes (`motion.reorder`, applied by
      // motion.css), so it is motion and stops dead under reduced motion. The
      // order itself is the DOM order, which is correct with no animation at
      // all.
      data-gs-motion="reorder"
      data-gs-animates="motion"
    >
      <span className="gs-leaderboard__sr" data-gs-scope="leaderboard" data-gs-part="summary">
        {rowSentence(entry, scoreLabel)}
      </span>
      <span className="gs-leaderboard__rank" data-gs-scope="leaderboard" data-gs-part="rank" aria-hidden="true">
        {entry.rank}
      </span>
      {/* The badge does not move, it changes glyph and colour, so it is
          emphasis and survives reduced motion. That is how a player who cannot
          see the reorder still sees which way they went. With no movement it is
          the drawn dash, and the slot keeps its width. */}
      <span
        className="gs-leaderboard__delta"
        data-gs-scope="leaderboard" data-gs-part="delta"
        data-gs-animates="emphasis"
        aria-hidden="true"
      >
        {movement ? (
          <>
            {(entry.delta ?? 0) > 0 ? '▲' : '▼'}
            {Math.abs(entry.delta ?? 0)}
          </>
        ) : (
          <span className="gs-leaderboard__still" />
        )}
      </span>
      {/* Player-supplied text, rendered as text by identity. Never
          dangerouslySetInnerHTML. The detail line rides as identity's own
          detail, under the name. The row carries data-gs-you, so identity is
          not told: two elements saying "you" in one row is two matches for a
          selector that wants one. */}
      <Identity
        player={{ id: entry.id, displayName: entry.name, avatarUrl: entry.avatarUrl }}
        size={broadcast ? 'large' : 'small'}
        aria-hidden="true"
      >
        {entry.detail}
      </Identity>
      <Stat
        className="gs-leaderboard__score"
        kind="score"
        value={entry.score}
        label={scoreLabel}
        format={formatScore}
        aria-hidden="true"
      />
    </li>
  )
}

/**
 * Move every row that changed place back to where it was, then release it, so
 * the browser animates the difference over the reorder token.
 *
 * Under reduced motion the token is `0ms`, so the release lands in the same
 * frame and nothing moves. The DOM order is already the new order either way,
 * which is the property that matters: with no animation at all the list is
 * still correct and still readable.
 */
function useReorder(deps: readonly unknown[]) {
  const listRef = React.useRef<HTMLOListElement>(null)
  const seen = React.useRef(new Map<string, number>())

  React.useLayoutEffect(() => {
    const list = listRef.current
    if (!list) return

    const rows = Array.from(list.querySelectorAll<HTMLElement>('[data-gs-player]'))
    const next = new Map<string, number>()
    const moved: Array<[HTMLElement, number]> = []

    for (const row of rows) {
      const id = row.getAttribute('data-gs-player')
      if (!id) continue
      const top = row.offsetTop
      next.set(id, top)
      const before = seen.current.get(id)
      if (before !== undefined && before !== top) moved.push([row, before - top])
    }
    seen.current = next
    if (moved.length === 0) return

    for (const [row, dy] of moved) {
      row.style.transition = 'none'
      row.style.transform = `translateY(${dy}px)`
    }
    // Read a layout property so the browser commits the offset before the
    // transition is handed back. Without it both writes coalesce and nothing
    // animates.
    void list.offsetHeight
    for (const [row] of moved) {
      row.style.transition = ''
      row.style.transform = ''
    }
  }, deps)

  return listRef
}

export function Leaderboard({
  entries,
  label = 'leaderboard',
  presentation = 'list',
  pinYou = true,
  scoreLabel = 'score',
  formatScore,
  emptyHeading = 'No scores yet',
  emptyBody = 'Play a round and this fills up.',
  emptyAction,
  className,
  ...rest
}: LeaderboardProps) {
  const empty = entries.length === 0
  const you = entries.find((entry) => entry.you)
  const listRef = useReorder([entries])

  // Is the player's own row on screen? Measured, not assumed.
  //
  // The pinned copy used to render whenever there was a `you` row at all, so a
  // six-row board showed the same rank twice, two rows apart, and every reader
  // called it a bug before they called it a feature. The design says "pinned
  // bottom when off-screen" and the prop's own doc says "while the list
  // scrolls": both describe a condition nothing was checking.
  //
  // An observer against the list's own scroll box is the honest way to know.
  // Counting rows would be a guess about a height the host controls.
  const [youIsVisible, setYouIsVisible] = React.useState(true)

  React.useEffect(() => {
    const list = listRef.current
    const row = list?.querySelector('[data-gs-you="true"]')
    // A list that cannot scroll can never hide the row, so there is nothing to
    // pin and no observer to run.
    if (!list || !row || list.scrollHeight <= list.clientHeight) {
      setYouIsVisible(true)
      return
    }
    const observer = new IntersectionObserver(
      (records) => setYouIsVisible(records.some((record) => record.isIntersecting)),
      { root: list, threshold: 0.6 },
    )
    observer.observe(row)
    return () => observer.disconnect()
  }, [entries, listRef])

  // The announcement problem: a reordering list is a screen-reader trap. Put
  // the list in a live region and one host update reads out every row that
  // moved, which is unusable at twenty rows and hostile at two hundred. So the
  // list announces nothing, and one polite status announces one thing: the
  // player's own rank, and only when it actually changed. Everyone else's
  // movement is visible, and readable on demand by walking the list.
  const [announcement, setAnnouncement] = React.useState('')
  const lastRank = React.useRef<number | undefined>(you?.rank)

  React.useEffect(() => {
    const rank = entries.find((entry) => entry.you)?.rank
    const before = lastRank.current
    lastRank.current = rank
    if (rank === undefined || before === undefined || before === rank) return
    setAnnouncement(
      `${STATE_WORD.you}, ${before > rank ? STATE_WORD.up : STATE_WORD.down} to ${rank}`,
    )
  }, [entries])

  return (
    <section
      {...rest}
      className={['gs-leaderboard', className].filter(Boolean).join(' ')}
      data-gs-component="leaderboard"
      data-gs-presentation={presentation}
      data-gs-empty={empty ? 'true' : undefined}
      aria-label={empty ? `${label}, ${STATE_WORD.empty}` : label}
    >
      {/* Always present, always polite, always one sentence. `aria-live` and
          no explicit `role`: a `role="status"` on an element that is empty
          until something happens reads as a control with no accessible name,
          and the live region is not a control. */}
      <div
        className="gs-leaderboard__sr"
        data-gs-scope="leaderboard" data-gs-part="announcement"
        aria-live="polite"
        aria-atomic="true"
      >
        {announcement}
      </div>

      {empty ? (
        <div className="gs-leaderboard__empty" data-gs-scope="leaderboard" data-gs-part="empty">
          <span className="gs-leaderboard__empty-glyph" data-gs-scope="leaderboard" data-gs-part="glyph" aria-hidden="true">
            ▚
          </span>
          <p className="gs-leaderboard__empty-heading" data-gs-scope="leaderboard" data-gs-part="label">
            {emptyHeading}
          </p>
          <p className="gs-leaderboard__empty-body" data-gs-scope="leaderboard" data-gs-part="detail">
            {emptyBody}
          </p>
          {emptyAction}
        </div>
      ) : (
        <ol className="gs-leaderboard__list" data-gs-scope="leaderboard" data-gs-part="list" ref={listRef}>
          {entries.map((entry) => (
            <Row
              key={entry.id}
              entry={entry}
              broadcast={presentation === 'broadcast'}
              scoreLabel={scoreLabel}
              formatScore={formatScore}
            />
          ))}
        </ol>
      )}

      {pinYou && you && !youIsVisible ? (
        // The held copy is visual. It repeats a row the screen reader can
        // already reach in the list, so announcing it twice is noise:
        // aria-hidden, and nothing inside it is focusable.
        //
        // The gap comes first. Without something between the list and the held
        // row there is nothing to say the list was cut, so the pinned row reads
        // as the next row and its rank looks wrong. The design draws it as an
        // ellipsis and so do we.
        <>
          <p
            className="gs-leaderboard__gap"
            aria-hidden="true"
            data-gs-scope="leaderboard"
            data-gs-part="gap"
          >
            ···
          </p>
          <ol className="gs-leaderboard__pinned" aria-hidden="true">
            <Row
              entry={you}
              pinned
              broadcast={presentation === 'broadcast'}
              scoreLabel={scoreLabel}
              formatScore={formatScore}
            />
          </ol>
        </>
      ) : null}
    </section>
  )
}

/* Leaderboard. Every value comes from a token; nothing here is a literal colour.

   The numbers are specimen 3e's (the phone board) and 3f's (the broadcast
   board), measured by design/twins/3e.json and 3f.json against the drawing
   with scripts/twin. Where the drawing uses a value no token carries, the
   twins file says which token stands in and why. */

.gs-leaderboard {
  display: grid;
  /* The list is the row that gives, so a host bounding the board bounds the
     list rather than the board overflowing its box. `minmax(0, 1fr)` rather
     than `1fr`: a grid track's default minimum is its content, so `1fr` alone
     refuses to shrink and the bound is ignored. That is why a board asked to
     fit 208px rendered at 1080 and the pinned row, which only exists when the
     list scrolls, could never appear. */
  grid-template-rows: minmax(0, 1fr);
  grid-auto-rows: auto;
  min-block-size: 0;
  /* The drawing runs one 8px gap down the whole column: row to row, row to
     the ellipsis, ellipsis to the held row. */
  gap: var(--gs-space-2);
  position: relative;
  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
}

/* The announcement and each row's sentence are for a screen reader only. They
   are clipped rather than hidden, because display:none is not announced. */
.gs-leaderboard__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* The list scrolls when the host bounds it, and not otherwise.

   A pinned row exists for exactly this case: the board is taller than the space
   the host gave it and the player's own row has scrolled away. Without these two
   lines nothing could ever scroll, so the pinned row was unreachable and the
   demo claimed a state it could not show. min-block-size: 0 is the part people
   miss: a grid or flex child refuses to shrink below its content without it, so
   the bound is ignored. */
.gs-leaderboard__list {
  overflow-y: auto;
  min-block-size: 0;
}

.gs-leaderboard__list,
.gs-leaderboard__pinned {
  display: grid;
  gap: var(--gs-space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

/* The held copy sits under the list and stays put while the list scrolls. */
.gs-leaderboard__pinned {
  position: sticky;
  bottom: 0;
  background: var(--gs-color-background);
}

/* -- a row ----------------------------------------------------------------- */
/* Specimen 3e: a 52px pill-cornered box, the chip height, with a 3px outline,
   10px between the things inside it and the score flush against a 12px right
   inset. A flex row rather than a grid: the score is the last item, so it sits
   at the one x every row shares, and the movement slot is always rendered so
   the avatars line up too. */
.gs-leaderboard__row {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
  box-sizing: border-box;
  block-size: var(--gs-size-chip);
  padding: 0 var(--gs-space-3) 0 var(--gs-space-gap);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-flat);

  /* The travel is motion.css's: the row carries data-gs-motion="reorder" and
     the shared rule transitions its transform over the reorder token on the
     drawing's curve, ease-in-out ("rows translate, never fade", 4a). It used
     to be ease-out here. The movement badge's colour transition lives on the
     badge, so it survives reduced motion. Under reduced motion the token is
     0ms and the row lands in its new place with no travel at all. */
}

/* A rank is a number in a row, which is the figure role: the display face at
   14px, weight 900, not the 22px stat that stands on a chip. The drawing draws
   it that size in every row and gives it a fixed slot so ranks 9 and 10 do not
   shift the row. */
.gs-leaderboard__rank {
  flex: none;
  inline-size: var(--gs-size-icon-control);
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  line-height: 1;
  /* Tabular, or a row shifts sideways the moment the rank goes from 9 to 10. */
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  color: var(--gs-color-ink-secondary);
}

/* Movement is the sign of data-gs-delta and nothing else. The arrow carries it
   without colour, the colour carries it without the arrow, and both survive
   reduced motion. The drawing sets it in the display face beside the rank, a
   step smaller; the figure token is the one size that face has in a row. */
.gs-leaderboard__delta {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--gs-space-1);
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  line-height: 1;
  color: var(--gs-color-positive-solid);
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-leaderboard__row[data-gs-delta^='-'] .gs-leaderboard__delta {
  color: var(--gs-color-negative-solid);
}

/* A row that did not move: the drawn dash, 20 by 3, in the muted ink. */
.gs-leaderboard__still {
  display: block;
  inline-size: calc(var(--gs-space-gap) * 2);
  block-size: var(--gs-stroke-ui);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-muted);
}

/* The player: identity's avatar disc and name. The row owns the sizes, because
   identity's small step (a 24px avatar) is for a presence list and the drawing
   draws the board's disc at 30px with the row's own 3px ring. */
.gs-leaderboard__row > [data-gs-component='identity'] {
  flex: 1 1 auto;
  min-inline-size: 0;
  gap: var(--gs-space-gap);
}

.gs-leaderboard__row > [data-gs-component='identity'][data-gs-size] [data-gs-part='avatar'] {
  /* The drawing's discs are border-box: a 30px disc is 30px with its ring. */
  box-sizing: border-box;
  inline-size: var(--gs-space-8);
  block-size: var(--gs-space-8);
  border-width: var(--gs-stroke-ui);
}

/* A player-supplied name is arbitrary length, and a row that grows to fit one
   pushes every score out of line. */
.gs-leaderboard__row [data-gs-component='identity'] [data-gs-part='label'] {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The row already says the word "score" in its sentence, so the stat's own
   label would be the third time a screen reader hears it and the first time a
   player sees it repeated down every row. Found by attribute, not by class, so
   a theme renaming stat's classes does not bring it back. */
.gs-leaderboard__score[data-gs-component='stat'] [data-gs-part='label'] {
  display: none;
}

/* A leaderboard score is a figure, not a score.

   The row is rank, name and score on one line, and the drawing sets the number
   at 14px in the display face, the same size as the rank across from it. At the
   score size, 34px, it was two and a half times the rank beside it and took the
   width the name needed. The size follows the room the number has, not the word
   "score". And no shadow: the display shadow belongs to a number standing on
   its own, and the drawing draws none in a row. */
.gs-leaderboard [data-gs-component='stat'][data-gs-stat='score'] .gs-stat__value {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  text-shadow: none;
}

/* -- the player's own row -------------------------------------------------- */
/* Specimen 3e draws it as a different object, not a marked row: the action
   height rather than the chip height, the control radius, the player colour as
   its fill with the dark ink on it, and a shelf beneath it so it stands off
   the board. Every part inside inherits that ink, including the movement badge,
   which is why the arrow keeps its shape and loses its colour here. */
.gs-leaderboard__row[data-gs-you='true'] {
  block-size: var(--gs-size-action);
  border-radius: var(--gs-radius-control);
  background: var(--gs-color-player);
  color: var(--gs-color-on-bright);
  box-shadow: var(--gs-depth-raised), var(--gs-depth-floating);
}

/* Named rather than inherited, because identity and stat each set their own
   ink on their root and a plain `inherit` picks that up, not the row's. */
.gs-leaderboard__row[data-gs-you='true'] .gs-leaderboard__rank,
.gs-leaderboard__row[data-gs-you='true'] .gs-leaderboard__delta,
.gs-leaderboard__row[data-gs-you='true'] [data-gs-component='identity'],
.gs-leaderboard__row[data-gs-you='true'] [data-gs-component='identity'] [data-gs-part='label'],
.gs-leaderboard__row[data-gs-you='true'] [data-gs-component='stat'] .gs-stat__value {
  color: var(--gs-color-on-bright);
}

/* The drawing sets the player's own name one weight heavier than the others;
   the action weight is that step, borrowed as identity borrows it. */
.gs-leaderboard__row[data-gs-you='true'] [data-gs-component='identity'] [data-gs-part='label'] {
  font-weight: var(--gs-type-action-font-weight);
}

/* -- the break in the list ------------------------------------------------- */
/* The gap between the visible rows and the held one. It is the whole difference
   between "your row is pinned" and "this list has rendered you twice": without
   something saying the list was cut, the held row reads as the next row and its
   rank looks wrong. The design draws three middle dots in the figure face. */
.gs-leaderboard__gap {
  margin: 0;
  text-align: center;
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  line-height: 1;
  color: var(--gs-color-muted);
  user-select: none;
}

/* -- broadcast ------------------------------------------------------------- */
/* Specimen 3f: the same rows on a big screen. Two columns, the hero height,
   the control radius, 14px between the parts, the rank in a 40px disc coloured
   by place, the name in the title face and the score at the stat size. */
.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__list {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--gs-space-3);
}

.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__row {
  gap: var(--gs-space-inset);
  block-size: var(--gs-size-icon-hero);
  padding: 0 var(--gs-space-4) 0 var(--gs-space-3);
  border-radius: var(--gs-radius-control);
}

/* The leader's row carries the raised highlight along its top. The drawing
   draws the highlight alone; the raised token brings the theme's shelf with it,
   and a highlight-only token is on the request list. */
.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__row[data-gs-rank='1'] {
  box-shadow: var(--gs-depth-raised);
}

/* The rank disc. Gold, silver and bronze for the podium places, the edge fill
   with a bright ring for everyone else. There is no silver or bronze token:
   ink-secondary and the reward base stand in, and both are on the request
   list. The numeral is the stat size, the nearest token to the drawing's 18. */
.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__rank {
  display: grid;
  place-items: center;
  box-sizing: border-box;
  inline-size: var(--gs-size-control-small);
  block-size: var(--gs-size-control-small);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge-high);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  color: var(--gs-color-ink);
}

.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__row:is([data-gs-rank='1'], [data-gs-rank='2'], [data-gs-rank='3']) .gs-leaderboard__rank {
  border-color: var(--gs-color-edge);
  color: var(--gs-color-on-bright);
}

.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__row[data-gs-rank='1'] .gs-leaderboard__rank {
  background: var(--gs-color-reward);
}

.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__row[data-gs-rank='2'] .gs-leaderboard__rank {
  background: var(--gs-color-ink-secondary);
}

.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__row[data-gs-rank='3'] .gs-leaderboard__rank {
  background: var(--gs-color-reward-base);
}

/* The avatar sits beside the disc at the same size, so the two read as a pair;
   the drawing's 36px has no token and 40 is the nearest. */
.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__row > [data-gs-component='identity'] {
  gap: var(--gs-space-inset);
}

.gs-leaderboard[data-gs-presentation='broadcast'] .gs-leaderboard__row > [data-gs-component='identity'][data-gs-size] [data-gs-part='avatar'] {
  inline-size: var(--gs-size-control-small);
  block-size: var(--gs-size-control-small);
}

.gs-leaderboard[data-gs-presentation='broadcast'] [data-gs-component='stat'][data-gs-stat='score'] .gs-stat__value {
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
}

/* -- empty ----------------------------------------------------------------- */
/* An empty leaderboard is a designed state, never a blank rectangle. */
.gs-leaderboard__empty {
  display: grid;
  justify-items: center;
  gap: var(--gs-space-2);
  padding: var(--gs-space-8) var(--gs-space-4);
  text-align: center;
  background: var(--gs-color-surface);
  border: var(--gs-stroke-hairline) dashed var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
}

.gs-leaderboard__empty-glyph {
  font-size: var(--gs-size-icon-hero);
  line-height: 1;
  color: var(--gs-color-muted);
}

.gs-leaderboard__empty-heading {
  margin: 0;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  color: var(--gs-color-ink);
}

.gs-leaderboard__empty-body {
  margin: 0;
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink-secondary);
}
